   await page.evaluate(r'''async(samples)=>{const s=wholeBuilding,r=s.renderer,g=r.gl;await s.pause();window.opticalEvents=[];const original=g.drawArrays.bind(g);g.drawArrays=function(...args){original(...args);const p=g.getParameter(g.CURRENT_PROGRAM),fbo=g.getParameter(g.DRAW_FRAMEBUFFER_BINDING);if(!fbo)return;let label='',attachments=0,mode=null;if(p===r.opticalRayProgram){label='optical-ray';attachments=3;mode=g.getUniform(p,g.getUniformLocation(p,'uReflection'))?1:0;}else if(p===r.apertureProgram){label='aperture-hit';attachments=3;mode=g.getUniform(p,g.getUniformLocation(p,'uRayMode'));}else if(p===r.shadeProgram){label='shade';attachments=1;mode=g.getUniform(p,g.getUniformLocation(p,'uRayMode'));}else return;const sc=g.getParameter(g.SCISSOR_BOX),active=samples.map((q,i)=>({...q,i,gy:544-1-q.y})).filter(q=>q.x>=sc[0]&&q.x<sc[0]+sc[2]&&q.gy>=sc[1]&&q.gy<sc[1]+sc[3]);if(!active.length)return;const oldF=g.getParameter(g.READ_FRAMEBUFFER_BINDING),oldB=g.getParameter(g.READ_BUFFER);g.bindFramebuffer(g.READ_FRAMEBUFFER,fbo);const x=Math.min(...active.map(q=>q.x)),y=Math.min(...active.map(q=>q.gy)),w=Math.max(...active.map(q=>q.x))-x+1,h=Math.max(...active.map(q=>q.gy))-y+1,values=active.map(q=>({sample:q.i,values:[]}));for(let a=0;a<attachments;a++){g.readBuffer(g.COLOR_ATTACHMENT0+a);const data=new Float32Array(w*h*4);g.readPixels(x,y,w,h,g.RGBA,g.FLOAT,data);for(let k=0;k<active.length;k++){const q=active[k],i=((q.gy-y)*w+q.x-x)*4;values[k].values.push([...data.slice(i,i+4)]);}}g.bindFramebuffer(g.READ_FRAMEBUFFER,oldF);g.readBuffer(oldB);window.opticalEvents.push({label,mode,values});};window.restoreOpticalHook=()=>{g.drawArrays=original;};}''',SAMPLES)
