   report['readback']=await page.evaluate(r'''async(samples)=>{const s=wholeBuilding,r=s.renderer,g=r.gl;await s.pause();restoreOpticalHook();const mod=await import('./r07/apertures.mjs');const sub=(a,b)=>a.map((v,i)=>v-b[i]),unit=a=>{const n=Math.hypot(...a);return a.map(v=>v/n)},cross=(a,b)=>[a[1]*b[2]-a[2]*b[1],a[2]*b[0]-a[0]*b[2],a[0]*b[1]-a[1]*b[0]],dot=(a,b)=>a.reduce((v,x,i)=>v+x*b[i],0);const camera=r.options,f=unit(sub(camera.target,camera.eye)),right=unit(cross(f,Math.abs(f[1])>.999?[0,0,1]:[0,1,0])),up=cross(right,f),pixels=r.readPixels(),q=[];for(const p of samples){const gy=543-p.y,uv=[(2*(p.x+.5)-640)/544,(2*(gy+.5)-544)/544],tan=Math.tan(camera.fov/2),rd=unit(f.map((v,i)=>v+tan*(uv[0]*right[i]+uv[1]*up[i]))),h=r.readHit(p.x,gy),cpu=mod.intersectAperturesRay(r.apertures,camera.eye,rd),glass=mod.apertureGlassInterval(r.apertures,h.objectId,camera.eye,rd),offset=(gy*640+p.x)*4;q.push({...p,rgba:[...pixels.slice(offset,offset+4)],primary:h,ray:{origin:camera.eye,direction:rd},dotNormal:dot(rd,h.normal),cpu,glass});}g.bindFramebuffer(g.FRAMEBUFFER,null);return{camera,width:r.canvas.width,height:r.canvas.height,gpu:r.gpu,events:window.opticalEvents,pixels:q,stats:s.lastStats,glError:g.getError()};}''',SAMPLES)
   await page.locator('#view').screenshot(path=str(out/'same-camera-optical-diagnostic.png'))
